fn solve(n: i8) -> Vec<char> {
    let n = n as usize;
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        if i < 2 {
            // For the first two positions, we can safely put 'a'
            result.push('a');
        } else {
            // Ensure s[i] != s[i-2]
            if result[i - 2] == 'a' {
                result.push('b');
            } else {
                result.push('a');
            }
        }
    }

    result
}

