    #[test]
    fn test_pattern() {
        // Check the condition s[i] != s[i+2]
        for n in 1..20 {
            let s = solve(n);
            for i in 0..(n as usize).saturating_sub(2) {
                assert_ne!(s[i], s[i+2]);
            }
            // Only 'a' and 'b' are used
            assert!(s.iter().all(|&c| c=='a' || c=='b'));
        }
    }
